export function firstLongWords(lines) {
  var result = [];

  for (var i = 0; i < lines.length; i++) {
    var found;

    for (const word of lines[i].split(" ")) {
      if (word.length > 4) {
        found = word;
        break;
      }
    }

    result.push(found || "-");
  }

  return result;
}
